function mergeStreams(streams) {
  const heap = []
  const less = (a, b) => a[0] < b[0]
  const push = item => {
    heap.push(item)
    let i = heap.length - 1
    while (i > 0) {
      const parent = (i - 1) >> 1
      if (!less(heap[i], heap[parent])) break
      ;[heap[i], heap[parent]] = [heap[parent], heap[i]]
      i = parent
    }
  }
  const pop = () => {
    const top = heap[0]
    const last = heap.pop()
    if (heap.length) {
      heap[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < heap.length && less(heap[l], heap[m])) m = l
        if (r < heap.length && less(heap[r], heap[m])) m = r
        if (m === i) break
        ;[heap[i], heap[m]] = [heap[m], heap[i]]
        i = m
      }
    }
    return top
  }
  streams.forEach((stream, s) => { if (stream.length) push([stream[0], s, 0]) })
  const merged = []
  while (heap.length) {
    const [value, s, i] = pop()
    merged.push(value)
    if (i + 1 < streams[s].length) push([streams[s][i + 1], s, i + 1])
  }
  return merged
}
